// GatewayScript.swift — GENERATED, DO NOT EDIT BY HAND.
// Source of truth: Iphone/Gateway/gateway.py
// The server-side gateway script is embedded in the PacketTunnel binary so the
// .appex bundle contains no loose script files (App Store 90035 rejection).
import Foundation

/// gateway.py bytes, base64-encoded. Decoded content is sent verbatim over SSH
/// to the server where the system python3 executes it. Must stay byte-identical
/// to Iphone/Gateway/gateway.py.
enum GatewayScript {
    static let base64Payload = ""

    static var bytes: Data? { Data(base64Encoded: base64Payload, options: .ignoreUnknownCharacters) }
}
